-- ============================================================================
-- UDSM e-Clearance & Transcript MIS — Complete Users & Students Seed Script
-- ============================================================================
-- Total Users    : 5333 (18 Institutional Staff + 5315 Students)
-- Student Source : Vetted_Certificates_Data-2024_2025.xlsx (Sheet1)
-- Excel Mirror   : deploy/udsm_users_bulk_upload.xlsx (100% identical user list)
-- Default Pass   : Clearance@2026! (BCrypt 10 rounds)
-- Target Engine  : MySQL 8.0.19+ (uses VALUES (...) AS new_row — zero #1287 warnings)
-- Idempotency    : Safe to re-run via ON DUPLICATE KEY UPDATE
-- ============================================================================

SET NAMES utf8mb4;
SET TIME_ZONE = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

-- Ensure additional colleges present in 2024/2025 vetted graduates exist in reference tables
AS `new_row`
ON DUPLICATE KEY UPDATE
  `name` = `new_row`.`name`,
  `description` = `new_row`.`description`,
  `is_active` = `new_row`.`is_active`;

AS `new_row`
ON DUPLICATE KEY UPDATE
  `name` = `new_row`.`name`;

-- ============================================================================
-- SECTION 1: USERS (5333 rows: 18 staff + 5315 students)
-- ============================================================================

AS `new_row`
ON DUPLICATE KEY UPDATE
  `email` = `new_row`.`email`,
  `password` = `new_row`.`password`,
  `full_name` = `new_row`.`full_name`,
  `first_name` = `new_row`.`first_name`,
  `middle_name` = `new_row`.`middle_name`,
  `last_name` = `new_row`.`last_name`,
  `registration_number` = `new_row`.`registration_number`,
  `programme` = `new_row`.`programme`,
  `college` = `new_row`.`college`,
  `department` = `new_row`.`department`,
  `academic_year` = `new_row`.`academic_year`,
  `graduation_year` = `new_row`.`graduation_year`,
  `year_of_study` = `new_row`.`year_of_study`,
  `role` = `new_row`.`role`,
  `is_active` = 1,
  `is_email_verified` = 1,
  `institutional_domain` = `new_row`.`institutional_domain`,
  `updated_at` = NOW(6);

